   899|    function validatePassword(pw) {
   900|      if (pw.length < 12) return 'Password must be at least 12 characters.';
   901|      if (pw.length > 128) return 'Password must be at most 128 characters.';
   902|      if (!/[A-Z]/.test(pw)) return 'Password must contain at least 1 uppercase letter.';
   903|      if (!/[0-9]/.test(pw)) return 'Password must contain at least 1 number.';
   904|      return null;
