   908|      try { new URL(url.startsWith('http') ? url : 'https://' + url); return true; } catch(e) { return false; }
   909|    }
   910|    function validateZip(zip) { return /^[A-Za-z0-9\s\-]{3,10}$/.test(zip.trim()); }
